-- VNV Events Pasta Station location cycle, local batch 03 (cities 31-45).
SET NAMES utf8mb4;
DELIMITER $$
DROP PROCEDURE IF EXISTS vnv_pasta_b03_preflight$$
CREATE PROCEDURE vnv_pasta_b03_preflight() BEGIN
IF DATABASE()<>'ophyra' THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Wrong local database'; END IF;
IF (SELECT COUNT(*) FROM cms_contents WHERE id_owner=2 AND site_key='vnvevents' AND slug IN ('pasta-station-catering-miami-beach','pasta-station-catering-brickell','pasta-station-catering-coconut-grove','pasta-station-catering-palmetto-bay','pasta-station-catering-sweetwater','pasta-station-catering-west-kendall','pasta-station-catering-north-miami','pasta-station-catering-north-miami-beach','pasta-station-catering-key-biscayne','pasta-station-catering-plantation','pasta-station-catering-hollywood','pasta-station-catering-cooper-city','pasta-station-catering-coral-springs','pasta-station-catering-pompano-beach','pasta-station-catering-deerfield-beach'))>0 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Pasta content collision'; END IF;
IF (SELECT COUNT(*) FROM cms_routes WHERE id_owner=2 AND site_key='vnvevents' AND route IN ('/locations/pasta-station-catering-miami-beach/','/locations/pasta-station-catering-brickell/','/locations/pasta-station-catering-coconut-grove/','/locations/pasta-station-catering-palmetto-bay/','/locations/pasta-station-catering-sweetwater/','/locations/pasta-station-catering-west-kendall/','/locations/pasta-station-catering-north-miami/','/locations/pasta-station-catering-north-miami-beach/','/locations/pasta-station-catering-key-biscayne/','/locations/pasta-station-catering-plantation/','/locations/pasta-station-catering-hollywood/','/locations/pasta-station-catering-cooper-city/','/locations/pasta-station-catering-coral-springs/','/locations/pasta-station-catering-pompano-beach/','/locations/pasta-station-catering-deerfield-beach/'))>0 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Pasta route collision'; END IF;
END$$
CALL vnv_pasta_b03_preflight()$$
DROP PROCEDURE vnv_pasta_b03_preflight$$
DELIMITER ;
SELECT id INTO @vnv_template_id FROM cms_templates WHERE id_owner=2 AND site_key='vnvevents' AND template_key='local-location-page' AND status='ACTIVE' LIMIT 1;
SELECT id INTO @vnv_category_id FROM cms_categories WHERE id_owner=2 AND site_key='vnvevents' AND slug='catering-services' AND is_active=1 AND applies_to_locations=1 LIMIT 1;
START TRANSACTION;
SET @vnv_content_id=LAST_INSERT_ID();
SET @vnv_content_id=LAST_INSERT_ID();
SET @vnv_content_id=LAST_INSERT_ID();
SET @vnv_content_id=LAST_INSERT_ID();
SET @vnv_content_id=LAST_INSERT_ID();
SET @vnv_content_id=LAST_INSERT_ID();
SET @vnv_content_id=LAST_INSERT_ID();
SET @vnv_content_id=LAST_INSERT_ID();
SET @vnv_content_id=LAST_INSERT_ID();
SET @vnv_content_id=LAST_INSERT_ID();
SET @vnv_content_id=LAST_INSERT_ID();
SET @vnv_content_id=LAST_INSERT_ID();
SET @vnv_content_id=LAST_INSERT_ID();
SET @vnv_content_id=LAST_INSERT_ID();
SET @vnv_content_id=LAST_INSERT_ID();
COMMIT;
SELECT COUNT(*) AS pasta_batch_01_contents FROM cms_contents WHERE id_owner=2 AND site_key='vnvevents' AND slug IN ('pasta-station-catering-miami-beach','pasta-station-catering-brickell','pasta-station-catering-coconut-grove','pasta-station-catering-palmetto-bay','pasta-station-catering-sweetwater','pasta-station-catering-west-kendall','pasta-station-catering-north-miami','pasta-station-catering-north-miami-beach','pasta-station-catering-key-biscayne','pasta-station-catering-plantation','pasta-station-catering-hollywood','pasta-station-catering-cooper-city','pasta-station-catering-coral-springs','pasta-station-catering-pompano-beach','pasta-station-catering-deerfield-beach');
SELECT COUNT(*) AS pasta_batch_01_routes FROM cms_routes WHERE id_owner=2 AND site_key='vnvevents' AND route IN ('/locations/pasta-station-catering-miami-beach/','/locations/pasta-station-catering-brickell/','/locations/pasta-station-catering-coconut-grove/','/locations/pasta-station-catering-palmetto-bay/','/locations/pasta-station-catering-sweetwater/','/locations/pasta-station-catering-west-kendall/','/locations/pasta-station-catering-north-miami/','/locations/pasta-station-catering-north-miami-beach/','/locations/pasta-station-catering-key-biscayne/','/locations/pasta-station-catering-plantation/','/locations/pasta-station-catering-hollywood/','/locations/pasta-station-catering-cooper-city/','/locations/pasta-station-catering-coral-springs/','/locations/pasta-station-catering-pompano-beach/','/locations/pasta-station-catering-deerfield-beach/') AND status='ACTIVE';
